package runner

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/procexec"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// session is one run's state, and the harness side (turnloop.Host) of its turn.
type session struct {
	cfg     Config
	id      string
	tr      *transcript
	hooks   *hooks.Hooks
	started time.Time
	texts   []string // what the agent said, in order: the result frame's text
	// named: hook payloads carry the transcript path. Cursor leaves it null
	// until the conversation's first tool call is past its preToolUse hooks
	// (recorded: runs/tool-failure), though the file is there from the first
	// record.
	named bool
	// added is the context the hooks have handed the agent so far (their
	// additional_context), in the order their events fired and, within an event,
	// the order the hooks are configured in.
	added []string
}

// keep adds the context the hooks of one event gave to the agent's: all of it,
// when several hooks gave some.
//
// sr:provides hook-additional-context/cursor
func (s *session) keep(ds []hooks.Decision) {
	for _, d := range ds {
		if d.Context != "" {
			s.added = append(s.added, d.Context)
		}
	}
}

// Context is what the agent has been handed by hooks, all of it (turnloop.Params.Added).
func (s *session) Context() string { return strings.Join(s.added, "\n") }

// Run plays one run: the stream's opening frames, the sessionStart hooks, the
// script's turns until its result, the sessionEnd hooks, and then the result
// frame, last on the stream. A single prompt runs to completion without
// interaction, streaming one record per line and ending with one result. The
// sessionEnd hook says the session completed: a non-interactive run has no
// other reason to report.
//
// The sessionStart hook fires once, before the first turn, and what it prints or
// exits with does not stop the session (recorded: runs/session-start-block); the
// payload says no source, as Cursor's does not.
//
// sr:provides noninteractive-run/cursor
// sr:provides session-end-hook/cursor
// sr:provides session-start-hook/cursor
// sr:docs https://cursor.com/docs/hooks#sessionend
// sr:docs https://cursor.com/docs/hooks#sessionstart
func Run(ctx context.Context, cfg Config) error {
	s := &session{cfg: cfg, id: coresession.NewID(), started: time.Now()}
	var err error
	if s.tr, err = newTranscript(cfg.Home, cfg.Dir, s.id); err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	conf, err := hooks.Load(cfg.Dir)
	if err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	s.hooks = &hooks.Hooks{Config: conf, Dir: cfg.Dir, Env: s.hookEnv, Common: s.common}
	s.forward(initFrame(s.id, cfg.Dir))
	s.forward(userFrame(s.id, cfg.Prompt))
	s.keep(s.hooks.Fire(ctx, hooks.SessionStart, hooks.NoSubject, map[string]any{"is_background_agent": false}))
	s.tr.user(cfg.Prompt) // the transcript file does not exist yet when the start hook runs
	_, runErr := turnloop.Run(ctx, s, turnloop.Params{Script: cfg.Script, Dir: cfg.Dir, Environ: cfg.Environ, Prompt: cfg.Prompt, Added: s.Context})
	s.named = true
	s.hooks.Fire(ctx, hooks.SessionEnd, hooks.NoSubject, map[string]any{
		"reason": "completed", "duration_ms": time.Since(s.started).Milliseconds(),
		"is_background_agent": false, "final_status": "completed",
	})
	s.tr.end()
	if runErr != nil {
		return fmt.Errorf("cursor-mock: %w", runErr)
	}
	s.forward(resultFrame(s.id, strings.Join(s.texts, ""), time.Since(s.started)))
	return nil
}

// hookEnv is the environment of a hook command: the harness's own, with the
// facts Cursor gives a hook (recorded: runs/subprocess-session-env,
// runs/nested-session-env).
func (s *session) hookEnv() []string {
	return procexec.Env(s.cfg.Environ,
		childenv.HookIdentity(s.cfg.Dir, s.common().TranscriptPath), childenv.HookDefaults(s.cfg.Dir, s.cfg.Version))
}

// common is what every hook payload carries now: the transcript path only once
// the conversation has a transcript.
func (s *session) common() hooks.Common {
	c := hooks.Common{SessionID: s.id, Dir: s.cfg.Dir, Version: s.cfg.Version}
	if s.named && s.tr.exists() {
		c.TranscriptPath = s.tr.path
	}
	return c
}

// forward prints one stream-json line.
func (s *session) forward(line []byte) { fmt.Fprintf(s.cfg.Stdout, "%s\n", line) }
package runner

import (
	"context"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/procexec"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// toolHost is the harness side (toolcall.Host) of one tool call.
type toolHost struct {
	s     *session
	quiet bool // leave the call off the stream
	call  toolexec.Call
	tool  hooks.Tool
	// refused: a before-tool hook refused the call; failure and result are what
	// the failure hook and the agent are told.
	refused         bool
	failure, result string
	res             toolexec.Result
}

func (h *toolHost) emit(line []byte) {
	if !h.quiet {
		h.s.forward(line)
	}
}

// Tool is the parameters a call to the named tool must carry.
func (h *toolHost) Tool(name string) ([]string, bool) { return toolexec.Required(name) }

// Before fires preToolUse and, for a shell command, beforeShellExecution; the
// first stage whose hooks refuse ends it. A refusal is worded as Cursor words
// it for the stage (recorded: runs/pretool-refusal).
//
// sr:docs https://cursor.com/docs/hooks#pretooluse
func (h *toolHost) Before(ctx context.Context, c toolcall.Call) (bool, string) {
	h.call = toolexec.FromScript(c.Name, c.Input)
	h.tool = hooks.Tool{Name: h.call.Name(), Input: h.call.HookInput(h.s.cfg.Dir), UseID: c.ID}
	if refused, msg := hooks.Refusal(h.s.hooks.Fire(ctx, hooks.PreToolUse, h.tool.Name, hooks.ToolFields(h.tool))); refused {
		h.failure, h.result = hooks.PreToolRefusal(msg)
		h.refused = true
		h.s.named = true
		return true, h.result
	}
	h.s.named = true
	if h.call.Kind == "shellToolCall" {
		own := map[string]any{"command": h.call.Command(), "cwd": "", "sandbox": false}
		if refused, msg := hooks.Refusal(h.s.hooks.Fire(ctx, hooks.BeforeShellExecution, h.call.Command(), own)); refused {
			h.failure, h.result = hooks.ShellRefusal(msg)
			h.refused = true
			return true, h.result
		}
	}
	return false, ""
}

// Execute runs the call, with the identity of the session in a shell
// command's environment, and prints its completed frame.
func (h *toolHost) Execute(ctx context.Context, _ toolcall.Call) toolcall.Result {
	env := procexec.Env(h.s.cfg.Environ, childenv.Identity(h.s.id), childenv.Defaults())
	h.res = toolexec.Execute(ctx, h.call, h.s.cfg.Dir, env)
	h.emit(completedFrame(h.s.id, h.tool.UseID, h.call, h.res.Frame))
	return toolcall.Result{Output: h.res.Output, Failed: h.res.Failed}
}

// After fires the hooks that follow a call: for one that ran, the events of
// its tool (afterShellExecution, afterFileEdit) and then the success hook with
// the tool's output, or the failure hook with its error; for a refused call,
// the failure hook with permission_denied. No hook's output changes what the
// agent is told of the result; the additional_context of the success and failure
// hooks is added to what the agent knows (recorded: runs/additional-context).
//
// sr:provides tool-failure-hook/cursor
// sr:provides posttooluse-payload/cursor
// sr:docs https://cursor.com/docs/hooks#posttoolusefailure
func (h *toolHost) After(ctx context.Context, _ toolcall.Call, _ toolcall.Result, kind corehooks.AfterTool) (string, bool) {
	own := hooks.ToolFields(h.tool)
	own["duration"] = ms(h.res.Took)
	if h.refused {
		own["error_message"], own["failure_type"], own["is_interrupt"] = h.failure, "permission_denied", false
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUseFailure, h.tool.Name, own))
		return "", false
	}
	switch {
	case h.call.Kind == "shellToolCall":
		h.s.hooks.Fire(ctx, hooks.AfterShellExecution, h.call.Command(), map[string]any{
			"command": h.call.Command(), "output": h.res.Output, "duration": ms(h.res.Took), "sandbox": false})
	case h.call.Kind == "editToolCall" && !h.res.Failed:
		h.s.hooks.Fire(ctx, hooks.AfterFileEdit, "Write", map[string]any{"file_path": h.call.Path(h.s.cfg.Dir), "edits": h.res.Edits})
	}
	switch kind {
	case corehooks.AfterSuccess:
		own["tool_output"] = h.res.ToolOutput
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUse, h.tool.Name, own))
	case corehooks.AfterFailure:
		own["error_message"], own["failure_type"], own["is_interrupt"] = h.res.ErrorMessage, "error", false
		h.s.keep(h.s.hooks.Fire(ctx, hooks.PostToolUseFailure, h.tool.Name, own))
	}
	return "", false
}

// Answer tells the agent how a call that did not run ended: refused by a hook,
// a tool the mock does not have, or input that lacks parameters (no hook
// fires for the last two; their wording is the mock's own).
func (h *toolHost) Answer(c toolcall.Call, a toolcall.Answer) {
	switch a.Kind {
	case toolcall.Refused:
		h.emit(rejectedFrame(h.s.id, c.ID, h.call, h.result))
	case toolcall.Unknown:
		h.emit(errorFrame(h.s.id, c.ID, toolexec.Call{Kind: "unknownToolCall"}, "Unknown tool: "+c.Name))
	case toolcall.Invalid:
		h.emit(invalidFrame(h.s.id, c, a.Missing))
	}
}
package runner

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// transcript is the conversation's record file, in the layout Cursor keeps
// (recorded: runs/*/samples/*/transcript): one JSON line per message, a user
// message first, assistant messages with their text and tool calls, and a
// closing turn_ended line. It is what the scenario script reads as
// A10N_MOCK_SESSION_FILE.
type transcript struct{ path string }

var nonAlnum = regexp.MustCompile(`[^A-Za-z0-9]`)

// newTranscript names the session's file under <home>/.cursor/projects/<project>/
// agent-transcripts/<session>/, where <project> is the workspace path (symlinks
// resolved by the entrypoint) with every non-alphanumeric character as "-". The
// file itself is written with the first record, after the start hook has run.
//
// sr:provides session-transcript-file/cursor
// sr:docs https://cursor.com/docs/hooks#common-schema
func newTranscript(home, dir, session string) (*transcript, error) {
	project := nonAlnum.ReplaceAllString(strings.TrimPrefix(dir, "/"), "-")
	d := filepath.Join(home, ".cursor", "projects", project, "agent-transcripts", session)
	if err := os.MkdirAll(d, 0o755); err != nil {
		return nil, err
	}
	return &transcript{path: filepath.Join(d, session+".jsonl")}, nil
}

func (t *transcript) add(line any) {
	b, _ := json.Marshal(line)
	if f, err := os.OpenFile(t.path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644); err == nil {
		_, _ = f.Write(append(b, '\n'))
		_ = f.Close()
	}
}

func (t *transcript) message(role string, blocks ...map[string]any) {
	t.add(map[string]any{"role": role, "message": map[string]any{"content": blocks}})
}

func (t *transcript) user(prompt string) {
	t.message("user", map[string]any{"type": "text", "text": "<user_query>\n" + prompt + "\n</user_query>"})
}

func (t *transcript) text(s string) {
	t.message("assistant", map[string]any{"type": "text", "text": s})
}

func (t *transcript) toolUse(name string, input map[string]any) {
	t.message("assistant", map[string]any{"type": "tool_use", "name": name, "input": input})
}

func (t *transcript) end() { t.add(map[string]any{"type": "turn_ended", "status": "success"}) }

func (t *transcript) exists() bool { _, err := os.Stat(t.path); return err == nil }
package hooks

import (
	"context"

	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
)

// Hooks fires a session's hooks.
type Hooks struct {
	Config Config
	// Dir is where project hooks run: the project root.
	Dir string
	// Env is the environment a hook command starts with, at the time of the event.
	Env func() []string
	// Common builds the fields every payload carries, at the time of the event.
	Common func() Common
}

// NoSubject is the subject of an event that has none (sessionStart and
// sessionEnd): every hook of the event runs, whatever its matcher.
const NoSubject = "\x00"

// Fire runs the commands configured for the event whose matcher selects its
// subject (the tool's name for a tool event, the command line for a shell
// event, "Write" for a file edit; an event with NoSubject takes every hook),
// all at once (Cursor runs an event's hooks side by side), each bounded by its
// timeout, with the event's payload on stdin. It returns what each decided, in
// the order configured. A project hook runs from the project root.
//
// sr:provides hook-command-handler/cursor
// sr:provides hook-matcher-filter/cursor
// sr:provides hooks-all-matching-run/cursor
// sr:docs https://cursor.com/docs/hooks#configuration
func (h *Hooks) Fire(ctx context.Context, e Event, subject string, own map[string]any) []Decision {
	var entries []Entry
	var cmds []corehooks.Command
	for _, entry := range h.Config.Entries(e) {
		if subject == NoSubject || corehooks.Matches(entry.Matcher, subject) {
			entries = append(entries, entry)
			cmds = append(cmds, corehooks.Command{Line: entry.Command, Timeout: entry.Timeout})
		}
	}
	if len(cmds) == 0 {
		return nil
	}
	outs := corehooks.RunAll(ctx, cmds, h.Common().Payload(e, own), corehooks.Runtime{Dir: h.Dir, Env: h.Env()})
	ds := make([]Decision, len(outs))
	for i, o := range outs {
		ds[i] = Interpret(e, entries[i], o)
	}
	return ds
}
package hooks

import (
	"encoding/json"
	"fmt"
	"strings"

	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
)

// Decision is what one hook command decided about the action it was asked
// about.
type Decision struct {
	// Permission is "deny", "ask" or "allow", or "" when the hook decided
	// nothing.
	Permission string
	// Blocked: the hook blocked by its exit status, not by its output.
	Blocked bool
	// Message is what a refusal says: the hook's stderr after "Hook blocked
	// with message:", the user_message of a deny, or the invalid-JSON notice.
	Message string
	// Context is the additional_context the hook gave, for an event that takes
	// it (sessionStart, postToolUse, postToolUseFailure).
	Context string
}

// failClosedNote opens what a fail-closed hook's failure says.
const failClosedNote = "Tool blocked because this hook is configured to fail closed (block when it fails). "

// Interpret reads one hook command's outcome for the event. Its exit status
// classifies it (the core's VerdictOf): 2 blocks, which is a deny; any other
// non-zero status fails open, and the hook's output is not read. A hook
// configured failClosed blocks on any failure instead: a non-zero status, or
// no output from a permission hook. On a permission event, output that is not
// a JSON object blocks the action for safety (a hook that prints nothing
// allows it); otherwise its permission and user_message are read.
//
// sr:provides hook-exit-code-semantics/cursor
// sr:docs https://cursor.com/docs/hooks#command-based-hooks
func Interpret(e Event, h Entry, o corehooks.Outcome) Decision {
	if !o.Counts() {
		// The core says a result is not read when the hook timed out (it and its
		// children were killed, and whatever it printed is discarded) or could not
		// start: the action goes on. Cursor's one difference: a hook that timed
		// out and fails closed blocks, saying it timed out after the limit it ran
		// under.
		// sr:provides hook-timeout/cursor
		// sr:docs https://cursor.com/docs/hooks#per-script-configuration-options
		if corehooks.FailsClosed(o, h.FailClosed) {
			return Decision{Permission: "deny", Blocked: true, Message: fmt.Sprintf("%sHook %q execution failed: Hook script timed out after %dms", failClosedNote, h.Command, o.Timeout.Milliseconds())}
		}
		return Decision{}
	}
	verdict := corehooks.NonBlockingError
	if o.Exit >= 0 {
		verdict = corehooks.VerdictOf(o.Exit, h.FailClosed)
	}
	switch verdict {
	case corehooks.Blocked:
		if o.Exit != 2 {
			return Decision{Permission: "deny", Blocked: true, Message: fmt.Sprintf("%sHook %q failed with exit code %d: %s", failClosedNote, h.Command, o.Exit, strings.TrimSpace(o.Stderr))}
		}
		return Decision{Permission: "deny", Blocked: true, Message: "Hook blocked with message: " + strings.TrimSpace(o.Stderr)}
	case corehooks.NonBlockingError:
		return Decision{}
	}
	out := strings.TrimSpace(o.Stdout)
	if e.addsContext() {
		// sr:provides hook-additional-context/cursor
		// sr:docs https://cursor.com/docs/hooks#posttooluse
		var p struct {
			Context string `json:"additional_context"`
		}
		if corehooks.IsJSONOutput(out, isOutputField) && json.Unmarshal([]byte(out), &p) == nil {
			return Decision{Context: p.Context}
		}
		return Decision{}
	}
	if !e.permission() {
		return Decision{}
	}
	if out == "" {
		if corehooks.SilentFails(out, h.FailClosed) {
			return Decision{Permission: "deny", Message: fmt.Sprintf("%sHook %q returned no output.", failClosedNote, h.Command)}
		}
		return Decision{}
	}
	var p struct {
		Permission  string `json:"permission"`
		UserMessage string `json:"user_message"`
	}
	// What counts as JSON output is the core's; the fields read from it are Cursor's.
	if !corehooks.IsJSONOutput(out, isOutputField) || json.Unmarshal([]byte(out), &p) != nil || !validPermission(p.Permission) {
		return Decision{Permission: "deny", Message: fmt.Sprintf("Hook %q returned invalid JSON. The command was blocked for safety.", h.Command)}
	}
	return Decision{Permission: p.Permission, Message: p.UserMessage}
}

func validPermission(p string) bool { return p == "" || p == "allow" || p == "deny" || p == "ask" }

// isOutputField reports whether a key is one a Cursor hook's output sets.
func isOutputField(key string) bool {
	switch key {
	case "permission", "user_message", "agent_message", "continue", "env", "additional_context":
		return true
	}
	return false
}

// Refusal is whether several hooks' decisions refuse the call, and what the
// refusal says: the core decides (a deny from any hook refuses, whatever the
// others decided, and a block by exit status outranks a deny in output); the
// messages of the hooks that refused are concatenated. An "ask" decides
// nothing: the mock models a run that no one is there to ask.
//
// sr:provides pretooluse-refusal/cursor
// sr:docs https://cursor.com/docs/hooks#configuration
func Refusal(ds []Decision) (refused bool, message string) {
	var vote corehooks.PreToolVote
	var blockMsgs, denyMsgs []string
	for _, d := range ds {
		switch {
		case d.Blocked:
			vote.Blocked = true
			blockMsgs = append(blockMsgs, d.Message)
		case d.Permission == "deny":
			vote.Denied = true
			denyMsgs = append(denyMsgs, d.Message)
		}
	}
	vote.BlockReason, vote.DenyReason = strings.Join(blockMsgs, "\n"), strings.Join(denyMsgs, "\n")
	return corehooks.PreToolRefusal([]corehooks.PreToolVote{vote})
}
package hooks

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"
)

// Entry is one hook configured for an event.
type Entry struct {
	// Command is the shell line to run.
	Command string
	// FailClosed: a failure of the hook (a non-zero exit status, no output)
	// blocks the action instead of letting it through.
	FailClosed bool
	// Matcher is a regular expression the event's subject must match for the
	// hook to run: "" and "*" match everything.
	Matcher string
	// Timeout stops the command after this long; zero is none of its own, and
	// the core applies the harness's default for it (corehooks.DefaultTimeout).
	Timeout time.Duration
}

// Config is the project's hooks: the entries configured for each event, in
// order.
type Config struct {
	entries map[Event][]Entry
}

// Load reads <dir>/.cursor/hooks.json. No file is no hooks. A hook's command,
// failClosed, matcher and timeout are modeled; its loop_limit, the prompt type
// of hook and the user, team and enterprise sources are not.
//
// sr:docs https://cursor.com/docs/hooks#configuration
func Load(dir string) (Config, error) {
	path := filepath.Join(dir, ".cursor", "hooks.json")
	raw, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		return Config{}, nil
	}
	if err != nil {
		return Config{}, err
	}
	var file struct {
		Hooks map[string][]struct {
			Command    string  `json:"command"`
			FailClosed bool    `json:"failClosed"`
			Matcher    string  `json:"matcher"`
			Timeout    float64 `json:"timeout"`
		} `json:"hooks"`
	}
	if err := json.Unmarshal(raw, &file); err != nil {
		return Config{}, fmt.Errorf("%s: %w", path, err)
	}
	c := Config{entries: map[Event][]Entry{}}
	for name, defs := range file.Hooks {
		for _, d := range defs {
			if d.Command != "" {
				c.entries[Event(name)] = append(c.entries[Event(name)], Entry{d.Command, d.FailClosed, d.Matcher, time.Duration(d.Timeout * float64(time.Second))})
			}
		}
	}
	return c, nil
}

// Entries are the hooks configured for the event, in order.
func (c Config) Entries(e Event) []Entry { return c.entries[e] }
package hooks

import "encoding/json"

// Common is what every payload carries beside its event's own fields.
type Common struct {
	SessionID string
	// TranscriptPath is the conversation's transcript file; "" is none yet.
	TranscriptPath string
	// Dir is the workspace root.
	Dir string
	// Version is the Cursor version the payloads report.
	Version string
}

// Tool names a tool call as the hooks see it.
type Tool struct {
	// Name is the tool's name in hooks: Shell, Read or Write.
	Name string
	// Input is the call's input as hooks see it.
	Input map[string]any
	// UseID identifies the call.
	UseID string
}

// Payload is the JSON a hook of the event reads on stdin: the common fields,
// then the event's own. The account's email is never known to the mock.
//
// sr:provides hook-common-payload/cursor
// sr:docs https://cursor.com/docs/hooks#common-schema
func (c Common) Payload(e Event, own map[string]any) []byte {
	p := map[string]any{
		"conversation_id": c.SessionID, "generation_id": c.SessionID, "session_id": c.SessionID,
		"model": "default", "hook_event_name": string(e), "cursor_version": c.Version,
		"workspace_roots": []string{c.Dir}, "user_email": nil, "transcript_path": nil,
	}
	if c.TranscriptPath != "" {
		p["transcript_path"] = c.TranscriptPath
	}
	for k, v := range own {
		p[k] = v
	}
	b, _ := json.Marshal(p)
	return b
}

// ToolFields are the fields a tool hook carries for its call.
func ToolFields(t Tool) map[string]any {
	return map[string]any{"tool_name": t.Name, "tool_input": t.Input, "tool_use_id": t.UseID, "cwd": ""}
}

package e2e

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// A test here replays a recorded cursor-agent run against the mock: the run's
// own setup (its hooks.json, hook scripts, prompt and env) is installed in a
// fresh workspace, the scenario script plays back the tool calls the real
// agent made (its tool_call started frames), and what the mock's hooks saw
// and what its stream shows is compared with what the recording shows. The
// recording is read from the run's newest committed sample.

// observed is what a run showed: the payloads its hooks read, in order, what
// the hook scripts logged of their own decisions, and the tool-call frames.
type observed struct {
	hooks   []map[string]any
	results []string
	frames  []string
	// raw are the payloads as the hooks read them, and ws and home the
	// workspace and the home the run used (set on the mock's side only).
	raw []map[string]any
	// envs are the environments the hook scripts logged of themselves.
	envs     []map[string]any
	ws, home string
}

// dropped are the fields a capture's normalizer removes (capture.sh): what
// differs between two runs of the same behaviour.
var dropped = map[string]bool{
	"transcript_path": true, "cwd": true, "workspace_roots": true, "user_email": true, "generation_id": true,
	"tool_use_id": true, "duration": true, "duration_ms": true, "model": true, "model_id": true, "model_params": true,
	"cursor_version": true, "conversation_id": true,
}

// normalize is capture.sh's normalizer: the dropped fields out, the session
// id as <SESSION_ID> and the workspace as <RUN>.
func normalize(v any, sid, ws string) any {
	switch x := v.(type) {
	case map[string]any:
		out := map[string]any{}
		for k, e := range x {
			if !dropped[k] {
				out[k] = normalize(e, sid, ws)
			}
		}
		return out
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = normalize(e, sid, ws)
		}
		return out
	case string:
		return strings.ReplaceAll(strings.ReplaceAll(x, sid, "<SESSION_ID>"), ws, "<RUN>")
	}
	return v
}

// unmodeledEnv drops from a recorded payload the two variables a shell
// command saw that the mock does not set (CURSOR_REQUEST_ID and
// CURSOR_RIPGREP_PATH: adr/modeled-surface).
func unmodeledEnv(v any) any {
	switch x := v.(type) {
	case map[string]any:
		out := map[string]any{}
		for k, e := range x {
			out[k] = unmodeledEnv(e)
		}
		return out
	case string:
		for _, name := range []string{"CURSOR_REQUEST_ID", "CURSOR_RIPGREP_PATH"} {
			x = strings.ReplaceAll(strings.ReplaceAll(x, name+"\n", ""), name+`\n`, "")
		}
		return x
	}
	return v
}

func readJSONL(t *testing.T, path string) []map[string]any {
	t.Helper()
	f, err := os.Open(path)
	require.NoError(t, err)
	defer f.Close()
	var out []map[string]any
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		var m map[string]any
		if json.Unmarshal(sc.Bytes(), &m) == nil && m != nil {
			out = append(out, m)
		}
	}
	return out
}

// frameName is how a tool_call or result frame is named for comparison.
func frameName(f map[string]any) string {
	typ, _ := f["type"].(string)
	sub, _ := f["subtype"].(string)
	if typ == "result" {
		return "result/" + sub
	}
	tc, _ := f["tool_call"].(map[string]any)
	for k, v := range tc {
		if !strings.HasSuffix(k, "ToolCall") {
			continue
		}
		outcome := ""
		if res, ok := v.(map[string]any)["result"].(map[string]any); ok {
			for rk := range res {
				if rk != "isBackground" {
					outcome = rk
				}
			}
		}
		return "tool_call/" + sub + "/" + k + "/" + outcome
	}
	return ""
}

// resultName names what a hook script logged of its own decision: its event
// and the exit status it gave (afterAgentThought, which the mock does not
// fire, is left out).
func resultName(m map[string]any) string {
	if _, ok := m["hook_ran"]; ok {
		return fmt.Sprintf("ran:%v:%v:%v:%v:%v", m["hook_ran"], m["event"], m["tool"], m["command"], m["phase"])
	}
	r, ok := m["hook_result"].(map[string]any)
	if !ok || r["event"] == "afterAgentThought" {
		return ""
	}
	if s, ok := r["script"].(string); ok {
		return fmt.Sprintf("%s:%v:%v", s, r["event"], r["command"])
	}
	return fmt.Sprintf("%v:%v", r["event"], r["exit"])
}

func jsonString(v any) string { b, _ := json.Marshal(v); return string(b) }

// recording is a run's newest committed sample.
func recording(t *testing.T, run string) (setup string, rec observed, calls []string, prompt string) {
	t.Helper()
	_, file, _, _ := runtime.Caller(0)
	root := filepath.Join(filepath.Dir(file), "..", "..", "snapshots", "runs", run)
	samples, err := filepath.Glob(filepath.Join(root, "samples", "*"))
	require.NoError(t, err)
	require.NotEmpty(t, samples, "run %s has no sample", run)
	sort.Strings(samples)
	sample := samples[len(samples)-1]
	for _, e := range readJSONL(t, filepath.Join(sample, "events.jsonl")) {
		p, _ := e["payload"].(map[string]any)
		switch {
		case e["event"] == "stream":
			if n := frameName(map[string]any{"type": e["type"], "subtype": e["subtype"], "tool_call": toolCall(e)}); n != "" {
				rec.frames = append(rec.frames, n)
			}
		case e["hook"] == "beforeReadFile" || e["hook"] == "afterAgentThought":
			// events the mock does not fire (adr/modeled-surface)
		case e["hook"] != nil:
			rec.hooks = append(rec.hooks, unmodeledEnv(p).(map[string]any))
		case p["hook_env"] != nil:
			rec.envs = append(rec.envs, hookEnv(p["hook_env"], ""))
		case p["hook_result"] != nil || p["hook_ran"] != nil:
			if n := resultName(p); n != "" {
				rec.results = append(rec.results, n)
			}
		}
	}
	sort.Strings(rec.results)
	b, err := os.ReadFile(filepath.Join(sample, "stream.jsonl"))
	require.NoError(t, err)
	for _, l := range strings.Split(string(b), "\n") {
		var f map[string]any
		if json.Unmarshal([]byte(l), &f) == nil && f["type"] == "tool_call" && f["subtype"] == "started" {
			calls = append(calls, l)
		}
	}
	p, err := os.ReadFile(filepath.Join(root, "setup", "prompt.txt"))
	require.NoError(t, err)
	return filepath.Join(root, "setup"), rec, calls, strings.TrimSpace(string(p))
}

// toolCall rebuilds the frame shape frameName reads from a normalized stream
// event ({event, type, subtype, tool, outcome}).
func toolCall(e map[string]any) map[string]any {
	tool, _ := e["tool"].(string)
	if tool == "" {
		return nil
	}
	body := map[string]any{}
	if o, _ := e["outcome"].(string); o != "" {
		body["result"] = map[string]any{o: true}
	}
	return map[string]any{tool: body}
}

func copyFile(t *testing.T, from, to string, mode os.FileMode) {
	t.Helper()
	b, err := os.ReadFile(from)
	require.NoError(t, err)
	require.NoError(t, os.MkdirAll(filepath.Dir(to), 0o755))
	require.NoError(t, os.WriteFile(to, b, mode))
}

// replay runs the recorded scenario against the mock and returns what it
// showed beside what the recording showed.
func replay(t *testing.T, run string) (got, want observed) {
	t.Helper()
	setup, want, calls, prompt := recording(t, run)
	ws, err := filepath.EvalSymlinks(t.TempDir())
	require.NoError(t, err)
	scratch := t.TempDir()
	copyFile(t, filepath.Join(setup, "hooks.json"), filepath.Join(ws, ".cursor", "hooks.json"), 0o644)
	scripts, _ := filepath.Glob(filepath.Join(setup, "*.sh"))
	for _, s := range scripts {
		copyFile(t, s, filepath.Join(ws, ".cursor", "hooks", filepath.Base(s)), 0o755)
	}
	writes := writtenContents(want)
	for i, c := range calls {
		line, rest := scriptCall(t, strings.ReplaceAll(c, "<RUN>", ws), writes)
		writes = rest
		require.NoError(t, os.WriteFile(filepath.Join(scratch, itoa(i)+".json"), []byte(line+"\n"), 0o644))
	}
	require.NoError(t, os.WriteFile(filepath.Join(scratch, "end.json"), []byte(`{"type":"result","subtype":"success","is_error":false,"result":"DONE"}`+"\n"), 0o644))
	script := filepath.Join(scratch, "scenario.sh")
	require.NoError(t, os.WriteFile(script, []byte("#!/bin/sh\nn=$(grep -c '\"type\":\"tool_use\"' \"$A10N_MOCK_SESSION_FILE\" 2>/dev/null)\nn=${n:-0}\nf=\""+scratch+"/$n.json\"\n[ -f \"$f\" ] || f=\""+scratch+"/end.json\"\ncat \"$f\"\n"), 0o755))
	logPath := filepath.Join(scratch, "payloads.jsonl")
	home := t.TempDir()
	env := []string{"PATH=" + os.Getenv("PATH"), "HOME=" + home, "HOOK_LOG=" + logPath, "TMPDIR=" + scratch, "A10N_MOCK_SCRIPT=" + script}
	if b, err := os.ReadFile(filepath.Join(setup, "env")); err == nil {
		for _, l := range strings.Split(string(b), "\n") {
			if l != "" {
				env = append(env, l)
			}
		}
	}
	cmd := exec.Command(binary, "-p", "--force", "--trust", "--output-format", "stream-json", prompt)
	cmd.Dir, cmd.Env = ws, env
	out, err := cmd.Output()
	require.NoError(t, err, "the mock failed: %s", out)

	var sid string
	for _, m := range readJSONL(t, logPath) {
		if s, ok := m["session_id"].(string); ok && sid == "" {
			sid = s
		}
	}
	for _, m := range readJSONL(t, logPath) {
		switch {
		case m["hook_event_name"] != nil && m["hook_event_name"] != "afterAgentThought":
			got.hooks = append(got.hooks, normalize(m, sid, ws).(map[string]any))
			got.raw = append(got.raw, m)
		case m["hook_env"] != nil:
			got.envs = append(got.envs, hookEnv(m["hook_env"], ws))
		case m["hook_result"] != nil || m["hook_ran"] != nil:
			if n := resultName(m); n != "" {
				got.results = append(got.results, n)
			}
		}
	}
	sort.Strings(got.results)
	got.ws, got.home = ws, home
	for _, l := range strings.Split(string(out), "\n") {
		var f map[string]any
		if json.Unmarshal([]byte(l), &f) == nil {
			if n := frameName(f); n != "" {
				got.frames = append(got.frames, n)
			}
		}
	}
	return got, want
}

// writtenContents are the contents the recorded run's Write calls wrote, in
// order, as its preToolUse hook saw them. A started frame's streamContent is
// only what the model had streamed so far, not always what ended in the file.
func writtenContents(rec observed) (out []string) {
	for _, h := range rec.hooks {
		if h["hook_event_name"] == "preToolUse" && h["tool_name"] == "Write" {
			out = append(out, h["tool_input"].(map[string]any)["content"].(string))
		}
	}
	return out
}

// scriptCall is the line the scenario script prints for a tool call the
// recorded agent made: the scenario protocol's assistant line with one tool_use
// block (the Claude Code names, which the mock maps onto Cursor's tools). A
// write's content is what the recorded hooks saw written (the started frame's
// streamContent is only what the model had streamed so far); writes are the
// recorded contents not yet used, and what is left after this call is returned.
func scriptCall(t *testing.T, frame string, writes []string) (string, []string) {
	t.Helper()
	var f map[string]any
	require.NoError(t, json.Unmarshal([]byte(frame), &f))
	id, _ := f["call_id"].(string)
	var name string
	var input map[string]any
	for kind, v := range f["tool_call"].(map[string]any) {
		body, ok := v.(map[string]any)
		if !ok || !strings.HasSuffix(kind, "ToolCall") {
			continue
		}
		args := body["args"].(map[string]any)
		switch kind {
		case "shellToolCall":
			name, input = "Bash", map[string]any{"command": args["command"]}
		case "readToolCall":
			name, input = "Read", map[string]any{"file_path": args["path"]}
		case "editToolCall":
			content, _ := args["streamContent"].(string)
			if len(writes) > 0 {
				content, writes = writes[0], writes[1:]
			}
			name, input = "Write", map[string]any{"file_path": args["path"], "content": content}
		}
	}
	require.NotEmpty(t, name, "a started frame naming no tool the mock runs: %s", frame)
	return jsonString(map[string]any{"type": "assistant", "message": map[string]any{"role": "assistant", "content": []any{
		map[string]any{"type": "tool_use", "id": id, "name": name, "input": input}}}}), writes
}

// hookEnv is what a hook logged of its environment, as the recording shows it:
// the workspace as <RUN>, without the path of cursor-agent's ripgrep, which the
// mock does not set, and without the transcript path, which cursor-agent hands
// a hook or not depending on a race (the last hook always has it).
func hookEnv(v any, ws string) map[string]any {
	out := map[string]any{}
	for k, e := range v.(map[string]any) {
		s, _ := e.(string)
		switch k {
		case "CURSOR_RIPGREP_PATH":
			continue
		case "CURSOR_TRANSCRIPT_PATH":
			continue // whether the file is named yet when a hook starts is a race in cursor-agent
		default:
			if ws != "" {
				s = strings.ReplaceAll(s, ws, "<RUN>")
			}
		}
		out[k] = s
	}
	return out
}

func itoa(i int) string { return strings.TrimSpace(jsonString(i)) }
package e2e

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// The scenario protocol is every mock's, unchanged: the script prints
// stream-json lines of Claude Code's shape (an assistant line whose tool_use
// block is the agent's tool call, a result line to end the run), and the mock
// prints Cursor's own frames for it.

// run plays a scenario script against the mock in a fresh workspace and
// returns its stdout, stderr and exit status.
func run(t *testing.T, script string, args ...string) (stdout, stderr string, code int) {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "scenario.sh")
	require.NoError(t, os.WriteFile(path, []byte(script), 0o755))
	cmd := exec.Command(binary, append([]string{"-p", "--output-format", "stream-json", "--script", path}, args...)...)
	cmd.Dir, cmd.Env = dir, []string{"PATH=" + os.Getenv("PATH"), "HOME=" + t.TempDir()}
	var out, errb strings.Builder
	cmd.Stdout, cmd.Stderr = &out, &errb
	err := cmd.Run()
	if exit, ok := err.(*exec.ExitError); ok {
		code = exit.ExitCode()
	}
	return out.String(), errb.String(), code
}

const (
	bashCall = `{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","id":"tu_1","name":"Bash","input":{"command":"echo hi"}}]}}`
	done     = `{"type":"result","subtype":"success","is_error":false,"result":"DONE"}`
)

// TestTheScriptRunsOncePerTurnAToolCallEndsTheTurnAndAResultEndsTheRun: the
// script plays the agent; each tool call ends its turn, the mock runs the tool
// and runs the script again, and the result ends the run.
// sr:proves turn-loop
// sr:proves noninteractive-run/cursor
func TestTheScriptRunsOncePerTurnAToolCallEndsTheTurnAndAResultEndsTheRun(t *testing.T) {
	out, _, code := run(t, `#!/bin/sh
printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"on it"}]}}'
if grep -q tool_use "$A10N_MOCK_SESSION_FILE"; then
  printf '%s\n' '`+done+`'
else
  printf '%s\n' '`+bashCall+`'
fi
`, "go")
	require.Equal(t, 0, code, out)
	var types []string
	for _, l := range strings.Split(strings.TrimSpace(out), "\n") {
		var f struct{ Type string }
		require.NoError(t, json.Unmarshal([]byte(l), &f))
		types = append(types, f.Type)
	}
	// init, the user's prompt, then per turn the agent's words, and for the
	// first the call (started, completed); the result is the last line.
	require.Equal(t, []string{"system", "user", "assistant", "tool_call", "tool_call", "assistant", "result"}, types, out)
	require.Contains(t, out, `"stdout":"hi\n"`)
	require.Contains(t, out, `"result":"on iton it"`)
}

// TestThePromptReachesTheScriptUnchanged: the script receives the user's
// prompt, unchanged, in A10N_MOCK_PROMPT.
// sr:proves scenario-prompt-env
func TestThePromptReachesTheScriptUnchanged(t *testing.T) {
	// The script says the prompt it was given before it ends the run, and
	// Cursor's result frame carries what the agent said, so the assertion is on
	// that result, not on the user frame the mock echoes from the command line.
	out, _, code := run(t, "#!/bin/sh\nprintf '%s\\n' '{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\"got:'\"$A10N_MOCK_PROMPT\"'\"}]}}'\n"+
		"printf '%s\\n' '"+done+"'\n", "fix", "the  bug")
	require.Equal(t, 0, code, out)
	lines := strings.Split(strings.TrimSpace(out), "\n")
	var last struct{ Type, Result string }
	require.NoError(t, json.Unmarshal([]byte(lines[len(lines)-1]), &last))
	require.Equal(t, "result", last.Type, out)
	require.Equal(t, "got:fix the  bug", last.Result)
}

// TestTheScriptCanReadTheSessionSoFar: the transcript so far is readable
// through A10N_MOCK_SESSION_FILE: the user's prompt first.
// sr:proves session-file-env
func TestTheScriptCanReadTheSessionSoFar(t *testing.T) {
	out, _, code := run(t, "#!/bin/sh\nif grep -q user_query \"$A10N_MOCK_SESSION_FILE\"; then printf '%s\\n' '{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\"saw-prompt\"}]}}'; fi\n"+
		"printf '%s\\n' '"+done+"'\n", "hello")
	require.Equal(t, 0, code, out)
	require.Contains(t, out, "saw-prompt")
}

// TestFiveIdenticalToolCallsInARowAbortTheRun: a script that never advances
// aborts the run with an error at the 5th identical call.
// sr:proves loop-guard
func TestFiveIdenticalToolCallsInARowAbortTheRun(t *testing.T) {
	out, stderr, code := run(t, "#!/bin/sh\nprintf '%s\\n' '"+bashCall+"'\n", "go")
	require.Equal(t, 1, code)
	require.Contains(t, stderr, "5 turns in a row")
	require.NotContains(t, out, `"type":"result"`, "an aborted run reports no result")
}

// TestStreamPartialOutputIsAcceptedAndChangesNothing: --stream-partial-output
// is accepted and ignored: the stream has the same frame types, and a single
// result frame, with or without it (no partial assistant deltas are modeled).
// sr:proves noninteractive-run/cursor
func TestStreamPartialOutputIsAcceptedAndChangesNothing(t *testing.T) {
	script := "#!/bin/sh\nprintf '%s\\n' '{\"type\":\"assistant\",\"message\":{\"role\":\"assistant\",\"content\":[{\"type\":\"text\",\"text\":\"hi\"}]}}'\nprintf '%s\\n' '" + done + "'\n"
	types := func(out string) (ts []string) {
		for _, l := range strings.Split(strings.TrimSpace(out), "\n") {
			var f struct{ Type string }
			require.NoError(t, json.Unmarshal([]byte(l), &f))
			ts = append(ts, f.Type)
		}
		return ts
	}
	plain, _, code := run(t, script, "go")
	require.Equal(t, 0, code, plain)
	partial, _, code := run(t, script, "--stream-partial-output", "go")
	require.Equal(t, 0, code, partial)
	require.Equal(t, types(plain), types(partial))
	require.Equal(t, 1, strings.Count(partial, `"type":"result"`))
}

// TestTheStreamsFramesCarryTheFieldsTheRecordingShows: recorded
// (runs/pretool-refusal), the init frame names the session, the working
// directory, the model and the permission mode; the user frame echoes the
// prompt; the result frame, last, carries the session, is_error false, the
// durations, a request id and the usage counts.
// sr:proves noninteractive-run/cursor
func TestTheStreamsFramesCarryTheFieldsTheRecordingShows(t *testing.T) {
	out, _, code := run(t, "#!/bin/sh\nprintf '%s\\n' '{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\"DONE\"}]}}'\nprintf '%s\\n' '"+done+"'\n", "say", "hi")
	require.Equal(t, 0, code, out)
	var frames []map[string]any
	for _, l := range strings.Split(strings.TrimSpace(out), "\n") {
		var f map[string]any
		require.NoError(t, json.Unmarshal([]byte(l), &f))
		frames = append(frames, f)
	}
	init, user, result := frames[0], frames[1], frames[len(frames)-1]
	require.Equal(t, "system", init["type"])
	require.Equal(t, "init", init["subtype"])
	sid, _ := init["session_id"].(string)
	require.NotEmpty(t, sid)
	require.NotEmpty(t, init["cwd"])
	require.NotEmpty(t, init["model"])
	require.Equal(t, "default", init["permissionMode"])
	require.Equal(t, sid, user["session_id"])
	content := user["message"].(map[string]any)["content"].([]any)[0].(map[string]any)
