package runner

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

func ms(d time.Duration) float64 { return float64(d.Microseconds()) / 1000 }

func jsonLine(v any) json.RawMessage { b, _ := json.Marshal(v); return b }

// toolFrame is a tool_call frame: the call's kind and args, and, once it has
// ended, its result.
func toolFrame(session, id, subtype string, c toolexec.Call, result map[string]any) []byte {
	body := map[string]any{"args": c.Args}
	if result != nil {
		body["result"] = result
	}
	return jsonLine(map[string]any{
		"type": "tool_call", "subtype": subtype, "call_id": id, "session_id": session,
		"tool_call": map[string]any{c.Kind: body},
	})
}

// startedFrame opens a tool call on the stream.
func startedFrame(session, id string, c toolexec.Call) []byte {
	return toolFrame(session, id, "started", c, nil)
}

// completedFrame ends a tool call that ran.
func completedFrame(session, id string, c toolexec.Call, result map[string]any) []byte {
	return toolFrame(session, id, "completed", c, result)
}

// rejectedFrame ends a call a hook refused: its result is a rejection with the
// reason the agent was given.
func rejectedFrame(session, id string, c toolexec.Call, reason string) []byte {
	rejected := map[string]any{"reason": reason, "isReadonly": false}
	if c.Kind == "shellToolCall" {
		rejected["command"], rejected["workingDirectory"] = c.Command(), ""
	} else {
		rejected["path"] = c.Args["path"]
	}
	return toolFrame(session, id, "completed", c, map[string]any{"rejected": rejected})
}

// invalidFrame ends a call whose input lacks required parameters. A Task call
// is worded as Cursor words it (recorded: runs/agent-input-validation); the
// mock words the other tools' calls itself.
func invalidFrame(session string, c toolcall.Call, missing []string) []byte {
	call := toolexec.FromScript(c.Name, c.Input)
	if call.Kind == "taskToolCall" {
		return toolFrame(session, c.ID, "completed", call,
			map[string]any{"error": map[string]any{"error": toolexec.InvalidArguments(missing)}})
	}
	return errorFrame(session, c.ID, call,
		fmt.Sprintf("%s: missing required parameter(s): %s", c.Name, strings.Join(missing, ", ")))
}

// errorFrame ends a call that could not run.
func errorFrame(session, id string, c toolexec.Call, message string) []byte {
	return toolFrame(session, id, "completed", c, map[string]any{"error": map[string]any{"errorMessage": message}})
}
// Package runner is one cursor-mock run: the session, the scenario script's
// turns, each tool call with its hooks, and the stream it prints.
package runner

import "io"

// Config is everything a run needs, read once at the mock's entrypoint.
type Config struct {
	// Script is the scenario script that plays the agent.
	Script string
	// Prompt is the user's prompt.
	Prompt string
	// Dir is the workspace: where the run starts and where project hooks live.
	Dir string
	// Environ is the mock's own environment, which its children inherit.
	Environ []string
	// Home is the user's home, where Cursor keeps ~/.cursor.
	Home string
	// Version is the Cursor version the mock reports in hook payloads.
	Version string
	Stdout  io.Writer
	Stderr  io.Writer
}
// Package toolexec executes the Cursor tools the mock models (Shell, Read,
// Write): the results Cursor reports for them, and what its hooks are told.
package toolexec

import (
	"context"
	"encoding/json"
	"path/filepath"
	"time"
)

// Call is a tool call as Cursor names it: the kind of its tool_call frame
// (shellToolCall, readToolCall, editToolCall) and that frame's args.
type Call struct {
	Kind string
	Args map[string]any
}

// Result is what a tool call came to.
type Result struct {
	// Failed: the call ran and failed.
	Failed bool
	// Frame is the result object of the call's completed stream frame.
	Frame map[string]any
	// ToolOutput is the call's result as postToolUse reports it, a JSON string.
	ToolOutput string
	// ErrorMessage is what postToolUseFailure reports when the call failed.
	ErrorMessage string
	// Output is what a shell command printed, for afterShellExecution.
	Output string
	// Background: the call started a background shell (no afterShellExecution
	// follows it; its end comes as a task notification).
	Background bool
	// Edits are the changes a file write made, for afterFileEdit.
	Edits []Edit
	Took  time.Duration
}

// Edit is one change a write made to a file.
type Edit struct {
	OldString string `json:"old_string"`
	NewString string `json:"new_string"`
}

// toolTable is the tools the mock models, by the name a scenario script gives
// them (the Claude Code names, with Cursor's Shell too): the kind of Cursor
// call, its name in hooks, and the parameters its input must carry.
var toolTable = map[string]struct {
	kind, hookName string
	required       []string
}{
	"Bash":  {"shellToolCall", "Shell", []string{"command"}},
	"Shell": {"shellToolCall", "Shell", []string{"command"}},
	"Read":  {"readToolCall", "Read", []string{"file_path"}},
	"Write": {"editToolCall", "Write", []string{"file_path", "content"}},
	// a sub-agent dispatch, whichever name it goes by (Task is Agent's old name)
	"Agent": {"taskToolCall", "Task", taskRequired},
	"Task":  {"taskToolCall", "Task", taskRequired},
}

// Required is the parameters a call to the named tool must carry, and whether
// the mock has the tool.
func Required(name string) ([]string, bool) {
	t, ok := toolTable[name]
	return t.required, ok
}

// FromScript is the Cursor call a scenario script's tool call stands for.
func FromScript(name string, input json.RawMessage) Call {
	var in map[string]any
	_ = json.Unmarshal(input, &in)
	str := func(k string) string { s, _ := in[k].(string); return s }
	c := Call{Kind: toolTable[name].kind, Args: map[string]any{}}
	switch c.Kind {
	case "shellToolCall":
		c.Args["command"] = str("command")
		// block_until_ms 0 (or run_in_background) is a shell left running in the
		// background (recorded: runs/task-notifications-bg).
		if v, ok := in["block_until_ms"].(float64); (ok && v == 0) || in["run_in_background"] == true {
			c.Args["isBackground"], c.Args["timeout"] = true, 0
			if d := str("description"); d != "" {
				c.Args["description"] = d
			}
		}
	case "readToolCall":
		c.Args["path"] = str("file_path")
	case "editToolCall":
		c.Args["path"], c.Args["streamContent"] = str("file_path"), str("content")
	case "taskToolCall":
		c.Args["description"], c.Args["prompt"] = str("description"), str("prompt")
	}
	return c
}

// Name is the tool's name in hooks: Shell, Read or Write.
func (c Call) Name() string {
	for _, t := range toolTable {
		if t.kind == c.Kind {
			return t.hookName
		}
	}
	return ""
}

func (c Call) str(key string) string { s, _ := c.Args[key].(string); return s }

// Path is the file a Read or Write call names, resolved against dir.
func (c Call) Path(dir string) string {
	p := c.str("path")
	if p != "" && !filepath.IsAbs(p) {
		p = filepath.Join(dir, p)
	}
	return p
}

// Background reports whether a Shell call asked to be left running.
func (c Call) Background() bool { b, _ := c.Args["isBackground"].(bool); return b }

// Description is what a Shell call says it does, if it says.
func (c Call) Description() string { return c.str("description") }

// Command is the shell line of a Shell call.
func (c Call) Command() string { return c.str("command") }

// HookInput is the call's input as hooks see it.
func (c Call) HookInput(dir string) map[string]any {
	switch c.Kind {
	case "shellToolCall":
		return map[string]any{"command": c.Command(), "cwd": c.str("workingDirectory"), "timeout": 30000}
	case "readToolCall":
		return map[string]any{"file_path": c.Path(dir)}
	case "taskToolCall":
		return map[string]any{"description": c.str("description"), "prompt": c.str("prompt"), "subagent_type": "generalPurpose"}
	default:
		return map[string]any{"file_path": c.Path(dir), "content": c.str("streamContent")}
	}
}

// Execute runs the call: a shell command in dir with env, or a file tool on
// the file it names.
func Execute(ctx context.Context, c Call, dir string, env []string) Result {
	switch c.Kind {
	case "shellToolCall":
		return shell(ctx, c, dir, env)
	case "readToolCall":
		return read(c, dir)
	case "taskToolCall":
		return task()
	}
	return write(c, dir)
}

func jsonString(v any) string { b, _ := json.Marshal(v); return string(b) }
package toolexec

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/internal/tools"
)

// shell runs a Shell call. A command exiting non-zero failed, whatever its
// status (grep finding nothing is a failure too): the result is a failure
// carrying the exit code and both streams, and the failure hook's
// error_message is what the command printed, or else "Command failed with
// exit code N" (recorded: runs/tool-failure, runs/shell-exit-status).
//
// sr:provides bash-tool-result/cursor
// sr:docs https://cursor.com/docs/hooks#aftershellexecution
func shell(ctx context.Context, c Call, dir string, env []string) Result {
	cwd := dir
	if wd := c.str("workingDirectory"); wd != "" {
		cwd = wd
	}
	start := time.Now()
	res := tools.Bash(ctx, c.Command(), cwd, env)
	took := time.Since(start)
	body := map[string]any{
		"command": c.Command(), "workingDirectory": c.str("workingDirectory"), "exitCode": res.ExitCode, "signal": "",
		"stdout": res.Stdout, "stderr": res.Stderr, "executionTime": took.Milliseconds(), "interleavedOutput": res.Output,
	}
	r := Result{Output: res.Output, Took: took, ToolOutput: jsonString(struct {
		Output   string `json:"output"`
		ExitCode int    `json:"exitCode"`
	}{res.Output, res.ExitCode})}
	if !res.Failed() {
		r.Frame = map[string]any{"success": body, "isBackground": false}
		return r
	}
	body["aborted"] = false
	r.Failed, r.Frame = true, map[string]any{"failure": body, "isBackground": false}
	r.ErrorMessage = strings.TrimSpace(res.Output)
	if r.ErrorMessage == "" {
		r.ErrorMessage = fmt.Sprintf("Command failed with exit code %d", res.ExitCode)
	}
	return r
}

