// empty string or "*" matches everything").
// sr:proves hook-matcher-filter/cursor
func TestAnEmptyStringMatcherMatchesEveryCall(t *testing.T) {
	got, want := replay(t, "hook-matchers-after-events")
	conforms(t, got, want)

