package hooks

// workaroundNote closes what the agent is told about a refused call.
const workaroundNote = "Agent note: Do not suggest workarounds to the blocked tool."

// PreToolRefusal is how a call refused at preToolUse is reported, from the
// hooks' message: the failure hook's error_message is the message itself, and
// the tool's result to the agent adds the note not to look for workarounds.
//
// sr:docs https://cursor.com/docs/hooks#pretooluse
func PreToolRefusal(message string) (failure, result string) {
	return message, message + "\n\n" + workaroundNote
}

// ShellRefusal is how a shell command refused at beforeShellExecution is
// reported: one text, for the failure hook's error_message and the tool's
// result alike.
//
// sr:docs https://cursor.com/docs/hooks#beforeshellexecution--beforemcpexecution
func ShellRefusal(message string) (failure, result string) {
	text := "Command execution was blocked by a hook: " + message +
		"\n\nTo view or modify configured hooks, go to Cursor Settings > Hooks.\n\n" + workaroundNote
	return text, text
}

// isOutputField reports whether a key is one a Cursor hook's output sets.
func isOutputField(key string) bool {
	switch key {
	case "permission", "user_message", "agent_message", "continue", "env", "additional_context":
		return true
	}
	return false
}

// Refusal is whether several hooks' decisions refuse the call, and what the
// refusal says: the core decides (a deny from any hook refuses, whatever the
// others decided, and a block by exit status outranks a deny in output); the
// messages of the hooks that refused are concatenated. An "ask" decides
// nothing: the mock models a run that no one is there to ask.
//
// sr:provides pretooluse-refusal/cursor
// sr:docs https://cursor.com/docs/hooks#configuration
func Refusal(ds []Decision) (refused bool, message string) {
	var vote corehooks.PreToolVote
	var blockMsgs, denyMsgs []string
	for _, d := range ds {
		switch {
		case d.Blocked:
			vote.Blocked = true
			blockMsgs = append(blockMsgs, d.Message)
		case d.Permission == "deny":
			vote.Denied = true
			denyMsgs = append(denyMsgs, d.Message)
		}
	}
	vote.BlockReason, vote.DenyReason = strings.Join(blockMsgs, "\n"), strings.Join(denyMsgs, "\n")
	return corehooks.PreToolRefusal([]corehooks.PreToolVote{vote})
}
